setup_files.csv.ts:
// BUG: no protection against CSV/formula injection. A field value starting
// with =, +, -, or @ becomes an executable formula when the exported CSV is
// opened in Excel/Sheets (e.g. a "name" of "=cmd|' /C calc'!A0" or a simpler
// "=1+1" that just corrupts data, or worse with DDE payloads).
export function toCsvField(value: string): string {
  if (value.includes(",") || value.includes('"') || value.includes("\n")) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

test_setup_files.test_csv.ts:
function assertEqual(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

import { toCsvField } from "./csv";

// benign values pass through unchanged
assertEqual(toCsvField("Ada Lovelace"), "Ada Lovelace", "plain value");

// existing comma/quote escaping still works
assertEqual(toCsvField("a,b"), '"a,b"', "comma still quoted");
assertEqual(toCsvField('say "hi"'), '"say ""hi"""', "quotes still doubled");

// every documented dangerous prefix must be neutralized with a leading '
for (const hostile of ["=1+1", "+1+1", "-1+1", "@SUM(A1:A9)", "\tformula", "\rformula"]) {
  const got = toCsvField(hostile);
  if (!got.startsWith("'")) {
    throw new Error(
      `toCsvField(${JSON.stringify(hostile)}) = ${JSON.stringify(got)} - ` +
        `dangerous prefix was not neutralized with a leading apostrophe`,
    );
  }
}

// the neutralized value must still contain the original text (just prefixed,
// not mangled) so the exported data is still readable
assertEqual(toCsvField("=1+1"), "'=1+1", "formula-neutralized value");

console.log("PASS");

reference_solution.csv.ts:
const DANGEROUS_PREFIXES = ["=", "+", "-", "@", "\t", "\r"];

export function toCsvField(value: string): string {
  let v = value;
  if (DANGEROUS_PREFIXES.some((p) => v.startsWith(p))) {
    // A leading apostrophe tells spreadsheet software to treat the cell as
    // literal text, neutralizing the formula trigger without altering the
    // visible value.
    v = "'" + v;
  }
  if (v.includes(",") || v.includes('"') || v.includes("\n")) {
    v = `"${v.replace(/"/g, '""')}"`;
  }
  return v;
}

